import React, { useState, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, ResponsiveContainer,
  PieChart, Pie, Cell, Legend
} from 'recharts';
import { TrendingUp, Activity, Box, ChevronDown, Filter, Download, Loader2, ArrowRight, ArrowLeft, AlertCircle } from 'lucide-react';

// SAFETY DATA: This is shown only if the JSON file is completely missing or broken
const MOCK_FALLBACK = {
  "No Data Loaded": {
    "kpis": { "totalSKUs": 0, "avgVariability": "0%", "highlyIntermittent": "0%" },
    "segmentation": [
      { "name": "High Intermittency", "value": 0, "combPercentage": 0, "volume": 0, "volPercentage": 0, "color": "#ef4444" },
      { "name": "High Variability", "value": 0, "combPercentage": 0, "volume": 0, "volPercentage": 0, "color": "#f59e0b" },
      { "name": "Low Variability", "value": 0, "combPercentage": 0, "volume": 0, "volPercentage": 0, "color": "#3b82f6" }
    ],
    "intermittency": [],
    "variability": []
  }
};

export default function App() {
  const [dashboardData, setDashboardData] = useState(null);
  const [selectedBU, setSelectedBU] = useState('');
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);

  // Load Tailwind for styling
  useEffect(() => {
    if (!document.getElementById('tailwind-cdn')) {
      const script = document.createElement('script');
      script.id = 'tailwind-cdn';
      script.src = "https://cdn.tailwindcss.com";
      document.head.appendChild(script);
    }
  }, []);

  useEffect(() => {
    const loadData = async () => {
      try {
        // Robust fetch strategy to handle different environments (Vite, CRA, GitHub Pages)
        const fetchUrls = [
          './dashboard_data.json',
          '/dashboard_data.json'
        ];
        
        // Safely check for PUBLIC_URL (prevents crashes in Vite/other bundlers)
        try {
          if (typeof process !== 'undefined' && process.env && process.env.PUBLIC_URL) {
            fetchUrls.push(`${process.env.PUBLIC_URL}/dashboard_data.json`);
          }
        } catch (envError) {
          // Ignore environment errors
        }

        let rawData = null;
        let lastError = "";

        for (const url of fetchUrls) {
          try {
            const res = await fetch(url);
            if (res.ok) {
              const text = await res.text();
              try {
                rawData = JSON.parse(text);
                if (rawData && Object.keys(rawData).length > 0) {
                  break; // Found and parsed successfully
                } else {
                  lastError = "The dashboard_data.json file was found but it is completely empty.";
                  rawData = null; // reset to trigger fallback
                }
              } catch (parseError) {
                lastError = `Found a file at ${url} but it returned HTML instead of JSON. Ensure dashboard_data.json is placed inside your 'public' folder.`;
              }
            } else {
              lastError = `Could not find dashboard_data.json at ${url}.`;
            }
          } catch (networkError) {
            lastError = `Network error trying to fetch ${url}.`;
          }
        }

        if (!rawData) {
          throw new Error(lastError || "Failed to load dashboard data.");
        }
        
        // Success
        setDashboardData(rawData);
        setSelectedBU(Object.keys(rawData)[0]);
        setError(null);
      } catch (err) {
        console.error("Data Load Error:", err);
        setError(err.message || "Something went wrong loading your data.");
        setDashboardData(MOCK_FALLBACK);
        setSelectedBU(Object.keys(MOCK_FALLBACK)[0]);
      } finally {
        setIsLoading(false);
      }
    };
    loadData();
  }, []);

  if (isLoading) return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-slate-50">
      <Loader2 className="animate-spin text-red-600 mb-4" size={48} />
      <p className="text-slate-500 font-medium animate-pulse">Loading Dashboard Intelligence...</p>
    </div>
  );

  const currentData = dashboardData ? (dashboardData[selectedBU] || MOCK_FALLBACK["No Data Loaded"]) : MOCK_FALLBACK["No Data Loaded"];
  const BUs = dashboardData ? Object.keys(dashboardData) : [];

  const MultiBarTooltip = ({ active, payload }) => {
    if (active && payload && payload.length) {
      return (
        <div className="bg-slate-800 text-white p-3 rounded-lg shadow-xl text-xs border border-slate-700">
          <p className="font-bold border-b border-slate-600 pb-1 mb-1">{payload[0].payload.band}</p>
          {payload.map((e, i) => (
            <div key={i} className="flex justify-between gap-4 py-0.5">
              <span style={{ color: e.color }}>{e.name}:</span>
              <span className="font-bold">{e.value}%</span>
            </div>
          ))}
        </div>
      );
    }
    return null;
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-800 pb-12" style={{ fontFamily: 'sans-serif' }}>
      {/* ERROR NOTICE */}
      {error && (
        <div className="bg-amber-500 text-white px-8 py-3 flex items-center justify-center gap-3 text-sm font-bold shadow-lg">
          <AlertCircle size={20} />
          <span>Notice: {error}</span>
        </div>
      )}

      <header className="bg-white border-b border-slate-200 px-8 py-4 flex justify-between items-center sticky top-0 z-10 shadow-sm">
        <div className="flex flex-col">
          <div className="text-2xl font-bold tracking-tight text-slate-900 flex items-baseline gap-1">
            <span>Thermo Fisher</span>
            <span className="text-sm font-light text-slate-400 tracking-widest uppercase">Scientific</span>
          </div>
          <p className="text-[10px] text-red-600 font-bold uppercase tracking-widest mt-0.5">Item/Customer Segmentation Dashboard</p>
        </div>

        <div className="flex items-center gap-4">
          <div className="relative">
            <button onClick={() => setIsDropdownOpen(!isDropdownOpen)} className="flex items-center gap-2 bg-slate-100 hover:bg-slate-200 px-4 py-2 rounded-lg font-bold border border-slate-200 text-sm transition-colors min-w-[200px] justify-between">
              <div className="flex items-center gap-2 overflow-hidden">
                <Filter size={14} className="text-red-600 shrink-0" />
                <span className="truncate">{selectedBU}</span>
              </div>
              <ChevronDown size={14} className={`transition-transform shrink-0 ${isDropdownOpen ? 'rotate-180' : ''}`} />
            </button>
            {isDropdownOpen && (
              <div className="absolute right-0 mt-2 w-80 bg-white border border-slate-200 rounded-xl shadow-2xl overflow-hidden z-20 max-h-96 overflow-y-auto">
                {BUs.map(bu => (
                  <button key={bu} onClick={() => { setSelectedBU(bu); setIsDropdownOpen(false); }} className={`w-full text-left px-4 py-3 text-sm transition-colors hover:bg-red-50 ${selectedBU === bu ? 'bg-red-50 text-red-700 font-bold border-l-4 border-red-600' : 'text-slate-600 border-l-4 border-transparent'}`}>{bu}</button>
                ))}
              </div>
            )}
          </div>
          <button className="bg-red-600 hover:bg-red-700 text-white px-4 py-2 rounded-lg font-bold text-sm flex items-center gap-2 shadow-sm transition-all active:scale-95">
            <Download size={14} /> Export
          </button>
        </div>
      </header>

      <main className="p-8 max-w-7xl mx-auto space-y-8">
        {/* KPI CARDS */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex items-center gap-5">
            <div className="bg-slate-50 p-4 rounded-xl text-slate-400"><Box size={24} /></div>
            <div>
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Total Combinations</p>
              <h3 className="text-2xl font-black">{(currentData.kpis?.totalSKUs || 0).toLocaleString()}</h3>
            </div>
          </div>
          <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex items-center gap-5">
            <div className="bg-slate-50 p-4 rounded-xl text-slate-400"><Activity size={24} /></div>
            <div>
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">High Variability %</p>
              <h3 className="text-2xl font-black">{currentData.kpis?.avgVariability || '0%'}</h3>
            </div>
          </div>
          <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex items-center gap-5">
            <div className="bg-red-50 p-4 rounded-xl text-red-600"><TrendingUp size={24} /></div>
            <div>
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Intermittent %</p>
              <h3 className="text-2xl font-black">{currentData.kpis?.highlyIntermittent || '0%'}</h3>
            </div>
          </div>
        </div>

        {/* SECTION 1: BREAKDOWN */}
        <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
          <div className="p-6 border-b border-slate-50">
            <h2 className="text-lg font-black flex items-center gap-2 uppercase tracking-tight">
              <div className="w-1.5 h-5 bg-red-600 rounded-full"></div>
              Segmentation Breakdown by Item/Customer
            </h2>
          </div>
          <div className="grid grid-cols-1 lg:grid-cols-12">
            <div className="lg:col-span-4 p-8 flex flex-col justify-center bg-slate-50/30">
              <div className="h-[280px]">
                {currentData.segmentation && currentData.segmentation.some(s => s.value > 0) ? (
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie 
                        data={currentData.segmentation} 
                        cx="50%" 
                        cy="50%" 
                        innerRadius={70} 
                        outerRadius={100} 
                        paddingAngle={4} 
                        dataKey="value" 
                        stroke="none"
                      >
                        {currentData.segmentation.map((e, i) => <Cell key={i} fill={e.color} />)}
                      </Pie>
                      <RechartsTooltip />
                    </PieChart>
                  </ResponsiveContainer>
                ) : (
                  <div className="h-full flex items-center justify-center border-2 border-dashed border-slate-200 rounded-full text-slate-300 font-bold uppercase text-xs">No Data to Plot</div>
                )}
              </div>
            </div>
            <div className="lg:col-span-8 overflow-x-auto">
              <table className="w-full text-left text-sm border-collapse">
                <thead className="bg-slate-100/50 text-slate-500 font-bold uppercase text-[10px] tracking-widest">
                  <tr>
                    <th className="px-6 py-4">Segment</th>
                    <th className="px-6 py-4 text-right">Combinations</th>
                    <th className="px-6 py-4 text-right">% of Combs</th>
                    <th className="px-6 py-4 text-right">Volume</th>
                    <th className="px-6 py-4 text-right">% of Volume</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {currentData.segmentation?.map((item, i) => (
                    <tr key={i} className="hover:bg-slate-50 transition-colors">
                      <td className="px-6 py-4 flex items-center gap-3">
                        <div className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: item.color }}></div>
                        <span className="font-bold text-slate-700">{item.name}</span>
                      </td>
                      <td className="px-6 py-4 text-right font-mono text-slate-600">{(item.value || 0).toLocaleString()}</td>
                      <td className="px-6 py-4 text-right font-bold">{item.combPercentage ?? 0}%</td>
                      <td className="px-6 py-4 text-right font-mono text-slate-600">{(item.volume || 0).toLocaleString()}</td>
                      <td className="px-6 py-4 text-right font-bold">{item.volPercentage ?? 0}%</td>
                    </tr>
                  ))}
                  {(!currentData.segmentation || currentData.segmentation.length === 0) && (
                    <tr><td colSpan="5" className="px-6 py-12 text-center text-slate-400 font-medium">No segment data available for this selection.</td></tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>

        {/* SECTION 2 & 3: BANDS */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          {/* INTERMITTENCY */}
          <div className="bg-white rounded-2xl shadow-sm border border-slate-100 p-6 flex flex-col">
            <h2 className="text-lg font-black flex items-center gap-2 uppercase tracking-tight mb-4">
              <div className="w-1.5 h-5 bg-blue-600 rounded-full"></div>
              Intermittency Bands Analysis
            </h2>
            <div className="flex justify-between px-2 mb-6 text-[10px] font-bold uppercase tracking-widest text-slate-400">
              <span><ArrowLeft size={12} className="inline mr-1"/> High Frequency</span>
              <span className="text-red-600 font-black">High Intermittency <ArrowRight size={12} className="inline ml-1"/></span>
            </div>
            <div className="h-[280px]">
              {currentData.intermittency && currentData.intermittency.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={currentData.intermittency} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                    <XAxis dataKey="band" axisLine={false} tickLine={false} tick={{ fill: '#94a3b8', fontSize: 9 }} dy={10} />
                    <YAxis axisLine={false} tickLine={false} tick={{ fill: '#94a3b8', fontSize: 9 }} tickFormatter={(v) => `${v}%`} />
                    <RechartsTooltip cursor={{ fill: '#f8fafc' }} content={<MultiBarTooltip />} />
                    <Legend verticalAlign="top" align="right" wrapperStyle={{ paddingBottom: '20px', fontSize: '10px', fontWeight: 'bold' }} />
                    <Bar dataKey="combPerc" name="% Combinations" fill="#2563eb" radius={[3, 3, 0, 0]} barSize={16} />
                    <Bar dataKey="volPerc" name="% Volume" fill="#fb923c" radius={[3, 3, 0, 0]} barSize={16} />
                  </BarChart>
                </ResponsiveContainer>
              ) : (
                <div className="h-full flex items-center justify-center border-2 border-dashed border-slate-100 rounded-xl text-slate-300 font-bold uppercase text-xs">No Intermittency Data</div>
              )}
            </div>
          </div>

          {/* VARIABILITY */}
          <div className="bg-white rounded-2xl shadow-sm border border-slate-100 p-6 flex flex-col">
            <h2 className="text-lg font-black flex items-center gap-2 uppercase tracking-tight mb-4">
              <div className="w-1.5 h-5 bg-teal-500 rounded-full"></div>
              Variability Bands Analysis
            </h2>
            <div className="flex justify-between px-2 mb-6 text-[10px] font-bold uppercase tracking-widest text-slate-400">
              <span><ArrowLeft size={12} className="inline mr-1"/> Low Variability</span>
              <span className="text-red-600 font-black">High Variability <ArrowRight size={12} className="inline ml-1"/></span>
            </div>
            <div className="h-[280px]">
              {currentData.variability && currentData.variability.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={currentData.variability} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                    <XAxis dataKey="band" axisLine={false} tickLine={false} tick={{ fill: '#94a3b8', fontSize: 9 }} dy={10} />
                    <YAxis axisLine={false} tickLine={false} tick={{ fill: '#94a3b8', fontSize: 9 }} tickFormatter={(v) => `${v}%`} />
                    <RechartsTooltip cursor={{ fill: '#f8fafc' }} content={<MultiBarTooltip />} />
                    <Legend verticalAlign="top" align="right" wrapperStyle={{ paddingBottom: '20px', fontSize: '10px', fontWeight: 'bold' }} />
                    <Bar dataKey="combPerc" name="% Combinations" fill="#0d9488" radius={[3, 3, 0, 0]} barSize={16} />
                    <Bar dataKey="volPerc" name="% Volume" fill="#818cf8" radius={[3, 3, 0, 0]} barSize={16} />
                  </BarChart>
                </ResponsiveContainer>
              ) : (
                <div className="h-full flex items-center justify-center border-2 border-dashed border-slate-100 rounded-xl text-slate-300 font-bold uppercase text-xs">No Variability Data</div>
              )}
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}